// Prototype-only camera controls and decorative object descriptions. No private role is switched.
const names=['沈知夏','周启明','林素琴','许承安','何映秋','陈默','演示席位7','演示席位8'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const decorations=[
 {id:'lamp',match:/lamp|fluorescent/,title:'旧白吊灯',text:'悬挂的旧式日光灯是房间照明装饰。转换视角时，会避让真正挡住圆桌的灯具，墙和屋顶始终保持封闭。'},
 {id:'window',match:/window/,title:'高窗',text:'灰蓝色的高窗提示室内空间的高度。可以环看它和周围墙面；这里没有新增可领取的线索。'},
 {id:'door',match:/door/,title:'会议室房门',text:'这是三维样稿会议室中的装饰房门，不是案发现场地图的新通道，也不提供走捷径或额外机关。'},
 {id:'cabinet',match:/cabinet|drawer/,title:'铁皮档案柜',text:'旧档案柜属于美术布景，不能搜索出尚未解锁的剧情材料。正式公开资料仍从桌上的公共资料夹按幕领取。'},
 {id:'paper',match:/paper-roll|bench|storage/,title:'纸卷与储物台',text:'纸卷和储物台只营造停工纸厂的空间感，不是可遗漏的搜证目标。'},
 {id:'architecture',match:/wall|ceiling|beam|column|floor|conduit|notice/,title:'建筑与墙面',text:'四面墙与高顶形成同一个实体房间。缩放只改变观看距离感，不会拉伸墙体、改变桌椅比例或穿墙。公告纸没有额外剧情文字。'}
];
function state(){return window.desk3D?.snapshot().exploration??{seat:null,yaw:0,pitch:0,zoom:1};}
function announce(message){const status=document.querySelector('#explore-status');if(status)status.textContent=message;}
function apply(patch){try{if(!window.desk3D?.explore)throw Error('场景探索模块尚未准备好');const result=window.desk3D.explore(patch);if(result?.ok===false)throw Error(result.reason||'发言期间锁定导演镜头');announce('画面已调整。私人身份和信封内容没有改变。');syncLabel();}catch(e){announce(e.message);window.deskPrototype.toast(e.message);}}
function open(){const active=window.deskPrototype.state().stage==='turn',s=state();window.deskPrototype.sheet('探索房间',`<div class="overline">只改变观看位置，不改变角色身份</div><h3>换一个角度看这间屋子</h3><p class="fine">在场景上拖动环看；双指捏合或滚轮缩放。查看建筑时，轻点窗、门、柜或灯。发言期间由导演镜头接管，结束后再自由探索。</p><label for="observe-seat">从谁的座位旁观</label><select id="observe-seat" class="explore-select" ${active?'disabled':''}><option value="">我的座位</option>${names.slice(0,window.deskPrototype.state().playerCount).map((n,i)=>`<option value="${i}" ${s.seat===i?'selected':''}>${i+1} · ${n}的座位</option>`).join('')}</select><div class="explore-grid">${[['left','向左环看'],['right','向右环看'],['up','抬高视线'],['down','压低视线'],['in','放大建筑 ＋'],['out','缩小视野 −'],['reset','回到我的视角']].map(([id,label])=>`<button class="action" data-explore="${id}" ${active?'disabled':''}>${label}</button>`).join('')}</div><p id="explore-status" class="explore-status" role="status">${active?'正在发言，暂时锁定导演镜头。':'旁观任何座位都不会打开别人的私人本。'}</p><button class="primary" data-explore="close">完成调整，回到圆桌 →</button><h3>查看建筑物件</h3><div class="inspect-list">${decorations.map(o=>`<button class="action" data-inspect="${o.id}">${o.title}　↗</button>`).join('')}</div><p class="privacy">这些说明只解释样稿的装饰与操作，不增加剧情证据。上帝视角也没有额外阅读权限。</p>`);}
function inspect(name){const item=decorations.find(o=>o.id===name||o.match.test(String(name)));if(!item)return;window.deskPrototype.sheet(item.title,`<div class="overline">建筑装饰 · 非剧情物证</div><h3>${item.title}</h3><p>${esc(item.text)}</p><button class="action" data-open="explore">‹ 返回探索工具</button><button class="primary" data-explore="close">回到房间</button>`);}
function syncLabel(){const e=document.querySelector('#camera-label');if(!e||!window.desk3D)return;const s=state(),p=window.deskPrototype.state(),observer=s.seat===null||s.seat===undefined?p.currentRole:s.seat;e.textContent=(s.seat===null||s.seat===undefined?'我的视角':'旁观 '+names[observer]+'的座位')+' · 私人身份 '+names[p.currentRole];}
document.addEventListener('change',e=>{if(e.target.id==='observe-seat')apply({seat:e.target.value===''?null:Number(e.target.value)});});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.inspect){inspect(b.dataset.inspect);return;}if(!b.dataset.explore)return;const k=b.dataset.explore,s=state();if(k==='close'){window.deskPrototype.close();return;}if(k==='reset'){try{const result=window.desk3D.resetExplore();if(result?.ok===false)throw Error(result.reason||'发言期间锁定导演镜头');announce('已回到自己的视角，缩放已复原。');syncLabel();}catch(err){announce(err.message);}return;}const delta={left:{yaw:Math.max(-Math.PI,s.yaw-.2)},right:{yaw:Math.min(Math.PI,s.yaw+.2)},up:{pitch:Math.min(.30,s.pitch+.06)},down:{pitch:Math.max(-.30,s.pitch-.06)},in:{zoom:Math.min(1.35,s.zoom+.1)},out:{zoom:Math.max(.65,s.zoom-.1)}}[k];if(delta)apply(delta);});
window.addEventListener('desk-state',syncLabel);window.deskExploration={open,inspect};
